using FT232H.Core.Spi;

namespace FT232H.Core.Hardware;

/// <summary>
/// SPI controller driven by the FT232H MPSSE engine.
/// </summary>
/// <remarks>
/// All methods are host-side asynchronous (they complete when the USB transfer and
/// driver round-trip complete). SPI clock edges themselves are generated by the
/// MPSSE hardware engine at the configured clock rate; host timing has no effect
/// on the on-wire waveform except through the configured clock and chip-select
/// setup. Multi-byte transfers keep chip select asserted for the whole payload.
/// </remarks>
public interface ISpiController
{
    SpiConfiguration Configuration { get; }

    /// <summary>Actual configured clock frequency in Hz (from the divisor formula).</summary>
    double ActualClockHz { get; }

    Task ApplyConfigurationAsync(SpiConfiguration configuration, CancellationToken cancellationToken = default);

    /// <summary>Executes one SPI transfer. Chip select handling follows the configuration.</summary>
    Task<SpiTransferResult> TransferAsync(SpiTransferRequest request, CancellationToken cancellationToken = default);

    /// <summary>Asserts (true) or releases (false) chip select in manual mode.</summary>
    Task SetChipSelectAsync(bool asserted, CancellationToken cancellationToken = default);
}